var frontierSnapshot = {"generatedAt":"2026-10-19T14:40:19.787Z","cadence":"Every Monday at 07:17 UTC","windowDays":45,"method":"Automated topic matching followed by newest-first ordering. This is a discovery feed, not an impact or efficacy ranking.","sources":[{"id":"europe-pmc","name":"Europe PMC","kind":"paper","url":"https://europepmc.org/RestfulWebService","note":"Newest peer-reviewed and indexed literature matching the atlas topic vocabulary."},{"id":"preprints","name":"Europe PMC preprint index","kind":"preprint","url":"https://europepmc.org/RestfulWebService","note":"Recent preprints indexed from source servers; each item links to its original record and is marked as not yet peer reviewed."},{"id":"clinicaltrials","name":"ClinicalTrials.gov","kind":"trial","url":"https://clinicaltrials.gov/data-api/api","note":"Recently updated registrations, not evidence that a treatment is effective."},{"id":"nibib","name":"NIH NIBIB News","kind":"news","url":"https://www.nibib.nih.gov/rss","note":"Current official biomedical-engineering news feed; item dates are shown as the weekly observation date when the feed omits them."}],"errors":[],"items":[{"id":"trial-nct07859683","kind":"trial","title":"TMS + Exposure Therapy for Pediatric OCD: Second Phase","date":"2026-10-19","observedAt":"2026-10-19","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT07859683","summary":"The goal of this clinical trial is to test transcranial magnetic stimulation (TMS) for improving the outcomes of Exposure with Response Prevention (ERP) in youth and young adults with Obsessive-Compulsive Disorder (OCD). Researchers will compare two groups: ERP with active (\"real\") TMS vs. ERP with sham (\"fake\") TMS. The first phase of this study found that active TMS+ERP normalized functioning in brain circuits that contribute to compulsive behavior. This second phase will test whether TMS-induced brain changes lead to improvements in OCD symptom severity. Participants will: * Complete clinical interviews, ques…","authors":"Bradley Hospital","venue":"NCT07859683 · NA","status":"recruiting","topics":["stimulate"]},{"id":"trial-nct05931913","kind":"trial","title":"TMS + Exposure Therapy for Pediatric OCD","date":"2026-10-19","observedAt":"2026-10-19","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT05931913","summary":"The goal of this clinical trial is to compare different forms of transcranial magnetic stimulation (TMS) for improving the outcomes of Exposure with Response Prevention (ERP) in youth and young adults with Obsessive-Compulsive Disorder (OCD). Researchers will compare three groups: ERP with one of two different active (\"real\") forms of TMS vs. ERP with sham (\"fake\") TMS. The main questions this study aims to answer are: 1) whether TMS normalizes functioning in brain circuits that contribute to compulsive behavior, and 2) whether TMS reduces compulsions during ERP. Participants will: * Complete clinical interviews…","authors":"Bradley Hospital","venue":"NCT05931913 · NA","status":"completed","topics":["stimulate"]},{"id":"trial-nct07880171","kind":"trial","title":"Intensive Home-based Transcranial Direct Current Stimulation for Long COVID","date":"2026-10-19","observedAt":"2026-10-19","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT07880171","summary":"The goal of this clinical trial is to learn if home-based transcranial direct current stimulation (tDCS) works to treat fatigue and other symptoms in adults with Long COVID. It will also learn about the safety and home adherence of this intervention. The main questions it aims to answer are: Does active tDCS lower fatigue severity (FAS score) compared to sham treatment? What are the effects of the treatment sequence on cognition, pain, anxiety, depression, and quality of life? Researchers will compare a sequence of active tDCS followed by sham tDCS to a sequence of sham tDCS followed by active tDCS in a crossove…","authors":"Hospital de Basurto","venue":"NCT07880171 · NA","status":"completed","topics":["stimulate"]},{"id":"trial-nct07880080","kind":"trial","title":"Transcutaneous Cervical Vagus Nerve Stimulation for Primary Dysmenorrhea","date":"2026-10-19","observedAt":"2026-10-19","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT07880080","summary":"This randomized, sham-controlled, parallel-group clinical trial will investigate the effects of bilateral transcutaneous cervical vagus nerve stimulation (tcVNS) on menstrual pain and related clinical outcomes in women with primary dysmenorrhea. Seventy women aged 18-30 years will be randomly allocated in a 1:1 ratio to either active tcVNS or sham stimulation. The intervention will be administered once daily for 8 minutes during the first three days of menstruation. Outcomes will include menstrual pain intensity, multidimensional pain characteristics, dysmenorrhea-related functional and emotional symptoms, anxie…","authors":"Sinop University","venue":"NCT07880080 · NA","status":"not yet recruiting","topics":["stimulate"]},{"id":"trial-nct06577454","kind":"trial","title":"Measuring the Effects of Neurostimulation on Risky and Ambiguous Decision-Making Capacity in People With and Without Substance Use Disorder","date":"2026-10-19","observedAt":"2026-10-19","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT06577454","summary":"Background: The purpose of this study is to understand how a type of brain stimulation, transcranial magnetic stimulation (TMS), may help those who use opioids such as heroin or methadone. TMS uses brief magnetic pulses to affect brain activity, and is approved by the FDA to treat some mental health problems and substance use. We will evaluate how TMS may help make it easier to make certain kinds of decisions that could help one manage their opioid use. Our findings may provide support for the use of brain stimulation as a treatment to reduce opioid use. Objective: To understand how TMS affects brain activity as…","authors":"National Institute on Drug Abuse (NIDA)","venue":"NCT06577454 · NA","status":"suspended","topics":["record","stimulate"]},{"id":"trial-nct04468932","kind":"trial","title":"Transcranial Magnetic Stimulation in Progressive Supranuclear Palsy","date":"2026-10-19","observedAt":"2026-10-19","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT04468932","summary":"The objective of this proposal is to investigate the effect of non-invasive repetitive cerebellar transcranial magnetic stimulation (rTMS) on motor control in progressive supranuclear (PSP). The central hypothesis is that augmenting cerebellar inhibition via cerebellar rTMS will decrease postural instability in patients with PSP. We will use functional near infrared spectroscopy (fNIRS) to examine changes in motor and premotor cortical activity after cerebellar rTMS.","authors":"Oregon Health and Science University","venue":"NCT04468932 · NA","status":"recruiting","topics":["stimulate"]},{"id":"trial-nct06561828","kind":"trial","title":"Developing Transcranial Neuromodulation Protocols for Learning and Decision-Making","date":"2026-10-19","observedAt":"2026-10-19","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT06561828","summary":"Background: People with substance use disorder (SUD) often have changes in brain function that can make it difficult to control drug-seeking behavior. These changes may heighten the urge to use drugs or lessen the desire to seek nondrug-related rewards. Researchers want to know how a technique called transcranial magnetic stimulation (TMS) may cause changes in brain activity that may help people with SUD. Objective: To test TMS in healthy volunteers. Eligibility: Healthy people aged 18 to 45 years who are right-handed. Design: Participants can volunteer for up to 5 different experiments. Each experiment requires…","authors":"National Institute on Drug Abuse (NIDA)","venue":"NCT06561828 · EARLY_PHASE1","status":"recruiting","topics":["record","stimulate"]},{"id":"trial-nct07874178","kind":"trial","title":"Temporal Interference Stimulation for Disorders of Consciousness","date":"2026-10-19","observedAt":"2026-10-19","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT07874178","summary":"This study aims to investigate whether a new non-invasive brain stimulation technique, called temporal interference stimulation, can influence brain activity and potentially improve signs of consciousness in patients with severe brain injuries and disorders of consciousness. After a severe brain injury, some patients may remain unable to communicate or interact normally with their environment because of impaired consciousness. Current treatment options to promote recovery are limited. Temporal interference stimulation is a new technique that uses mild electrical currents applied through electrodes placed on the…","authors":"Centre Hospitalier Universitaire de Liege","venue":"NCT07874178 · NA","status":"not yet recruiting","topics":["record","stimulate"]},{"id":"trial-nct07879924","kind":"trial","title":"Dual Neuromodulation for Depression: Boosting TMS With tES","date":"2026-10-19","observedAt":"2026-10-19","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT07879924","summary":"Major depressive disorder (MDD) is a common and disabling condition. Transcranial magnetic stimulation (TMS) is an established non-invasive neuromodulation treatment for depression, but clinical response varies considerably between individuals. One possible reason for this variability is that the effects of TMS may depend on the pattern of ongoing brain activity at the time stimulation is delivered. This mechanistic, randomised, single-blind study will investigate whether synchronising TMS with transcranial alternating current stimulation (tACS), a form of weak electrical brain stimulation, can enhance the neuro…","authors":"Mersey Care NHS Trust","venue":"NCT07879924 · NA","status":"not yet recruiting","topics":["record","stimulate","personal"]},{"id":"trial-nct01036581","kind":"trial","title":"Advanced Functional and Structural MRI Techniques for Neuropharmacological Imaging","date":"2026-10-19","observedAt":"2026-10-19","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT01036581","summary":"Background: \\- Functional and structural magnetic resonance imaging (MRI) techniques have allowed researchers to map and study how the brain works when at rest and when engaged in specific tasks. MRI scans have provided more information about how drugs affect the brain, and about how drug addiction changes the brain and influences behavior, mood, and thinking processes. To better understand the underlying mechanism of drug addiction and to develop strategies for more effective treatment, researchers are interested in developing new MRI techniques to study the effects of addiction on the brain. Objectives: \\- To…","authors":"National Institute on Drug Abuse (NIDA)","venue":"NCT01036581 · NA","status":"recruiting","topics":["record"]},{"id":"preprint-10.64898/2026.10.12.758639","kind":"preprint","title":"Fast Generalized Longitudinal Functional Principal Components Analysis with Applications to Population-Level Neuronal Dynamics","date":"2026-10-18","observedAt":"2026-10-19","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.10.12.758639","summary":"Functional data are widely collected across many fields. One approach for modeling functional data collected across repeated measures is longitudinal functional PCA (LFPCA), which allows for the decomposition of variability at multiple levels. However, existing estimation approaches for LFPCA can be computationally demanding for large or high-dimensional datasets. Here, we propose fast generalized LFPCA, a novel estimation technique that bins data along the functional domain and fits a marginal mixed model at each bin. Simulation results show that the proposed method is orders of magnitude faster than existing t…","authors":"Duffy KA, Pai N, Schneck D, Kozienko G, Zheng L, Xenopoulos-Oddsson A, Wang J, Johnson LA, Vitek J, Fiecas M, Cui E.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["stimulate"]},{"id":"preprint-10.64898/2026.10.11.758333","kind":"preprint","title":"Modeling Paralinguistic Features for Speech Neuroprostheses: A Systematic Review","date":"2026-10-18","observedAt":"2026-10-19","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.10.11.758333","summary":"Recent advances in brain-computer interface (BCI) technology have brought speech neuroprostheses closer to restoring naturalistic communication for individuals with severe motor or speech impairments. Although current systems can decode phonemic and lexical information from cortical activity, they often fail to capture paralinguistic dimensions such as intonation, prosody, loudness, and affect that are essential for conveying emotion and intent. This review synthesizes emerging research on modeling and incorporating paralinguistic features into speech neuroprosthetic design. Foundational studies have mapped the…","authors":"Yenikapati MS, Deshpande S, Desai SP, Santine DD, Roghani AK.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["restore"]},{"id":"preprint-10.64898/2026.10.12.758428","kind":"preprint","title":"Cooperative processing of visual threat across collicular pathways","date":"2026-10-18","observedAt":"2026-10-19","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.10.12.758428","summary":"Rapid defensive actions require the transformation of sensory cues into appropriate motor responses. The superior colliculus is central to this transformation, containing defined cell-types that form parallel output pathways linking visual inputs to distinct behaviors. However, whether these pathways act independently or cooperate remains unclear. Here we combine cell-type-specific inhibition, large-scale electrophysiology, and functional ultrasound imaging to determine how these pathways contribute to visually evoked defensive behaviors. Inhibiting either narrow-field or wide-field neurons impaired escape to ov…","authors":"Nuttin B, Sans-Dublanc A, Chrzanowska A, Liu C, Hanson L, Drakaki Z, Luyks R, Bruystreen A, Philipon A, Grillet M, Kuhn N, Goncalves P, Montaldo G, Bonin V, Urban A, Farrow K.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record","stimulate"]},{"id":"preprint-10.21203/rs.3.rs-10991097/v1","kind":"preprint","title":"Behavioral and neural modulation effects of transcranial pulse stimulation of the dorsal cingulate cortex and anterior insula cortex in healthy adults: A prospective, randomized, sham-controlled trial","date":"2026-10-18","observedAt":"2026-10-19","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.21203/rs.3.rs-10991097/v1","summary":"Abstract Background Transcranial pulse stimulation (TPS) is a novel non-invasive brain stimulation technique with promising neuromodulation effects. No studies have examined target-specific deep brain TPS. This study assessed whether TPS of the dorsal anterior cingulate cortex (dACC) and anterior insular cortex (AIC) modulates risk-taking behavior and brain circuits in healthy participants. Methods Seventy-five healthy adults were randomized in this subjects/raters-blind study to 10 sessions of active dACC-TPS, active AIC-TPS, or sham-TPS over 2 weeks. Balloon Analog Risk Task (BART), a psychological measure of…","authors":"Qin PP, Chak IK, Lin TTZ, Jin M, Kan RL, Zhang BB, Xia AW, Wang SX, Lam V, Lin J, Yuan T, Chau BK, Bergmann TO, Padberg F, Kranz GS.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["stimulate"]},{"id":"paper-pmc-pmc13664290","kind":"paper","title":"Large-scale brain network modulation by auricular vagus neuromodulation in major depressive disorder: a systematic review of neuroimaging evidence","date":"2026-10-16","observedAt":"2026-10-19","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://europepmc.org/article/PMC/PMC13664290","summary":"Europe PMC does not provide an abstract for this record.","authors":"Su Y, Liu Y, Chen J, Li X, Liu T, Fu W.","venue":"Frontiers in psychiatry","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"paper-pmc-pmc13658202","kind":"paper","title":"MuscleSCS: a standardized programming framework combining neural neuromodulation and spinally mediated paraspinal muscle modulation","date":"2026-10-16","observedAt":"2026-10-19","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://europepmc.org/article/PMC/PMC13658202","summary":"Europe PMC does not provide an abstract for this record.","authors":"Morgalla M.","venue":"Frontiers in pain research (Lausanne, Switzerland)","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"paper-pmc-pmc13655047","kind":"paper","title":"Effects of globus pallidus internus deep brain stimulation on freezing of gait in Parkinson's disease: a prospective short-term single-arm study","date":"2026-10-16","observedAt":"2026-10-19","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://europepmc.org/article/PMC/PMC13655047","summary":"Europe PMC does not provide an abstract for this record.","authors":"Zhang P, Cao L, Wang T, Li D, Chen S, Liu J, He H, Zhou H.","venue":"Frontiers in aging neuroscience","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"paper-pmc-pmc13657627","kind":"paper","title":"Robust and replicable effects of ageing on resting-state brain electrophysiology measured with MEG","date":"2026-10-16","observedAt":"2026-10-19","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://europepmc.org/article/PMC/PMC13657627","summary":"Europe PMC does not provide an abstract for this record.","authors":"Quinn A, Pitt J, Kohl O, Gohil C, van Es M, Nobre A, Woolrich M.","venue":"eLife","status":"Peer-reviewed / indexed","topics":["record"]},{"id":"paper-pmc-pmc13653557","kind":"paper","title":"Incidental Finding of an Asymptomatic Perielectrode Cyst After Deep Brain Stimulation for Parkinson’s Disease","date":"2026-10-16","observedAt":"2026-10-19","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://europepmc.org/article/PMC/PMC13653557","summary":"Europe PMC does not provide an abstract for this record.","authors":"Du Four S, Vandamme S, Vanhauwaert D, Van Lerbeirghe J, Van Damme O.","venue":"Cureus","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"paper-pmc-pmc13674484","kind":"paper","title":"Noninvasive ultrashort wave neuromodulation enhances glymphatic clearance to alleviate traumatic brain edema and Alzheimer’s pathology","date":"2026-10-16","observedAt":"2026-10-19","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://europepmc.org/article/PMC/PMC13674484","summary":"Europe PMC does not provide an abstract for this record.","authors":"Liu J, Xu C, Ruan H, Zhang K, Wang F, Qin Q, Li X, Chen Y, Tan Y, Qiu Y, Chen H, Wang Y, Yang Z, Zhang Y, Zhu Y, Chang C, Jiang X, Peng N.","venue":"Science advances","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"paper-10.3238/arztebl.m2026.0156","kind":"paper","title":"Obsessive-Compulsive Disorder in Adulthood: Etiology, Diagnosis, and Treatment.","date":"2026-10-16","observedAt":"2026-10-19","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.3238/arztebl.m2026.0156","summary":"Background Obsessive-compulsive disorder (OCD) is common, with a lifetime prevalence of 1.3-4.1%, and it usually markedly impairs the quality of life of those affected. The rationale behind this article is to present an up-to-date review of the etiology, diagnosis, and treatment recommendations of OCD in adults. Methods This narrative review is based on relevant publications, including the revised German clinical practice guideline on OCD. Results Genetic factors are estimated to account for 50% of the variance in OCD; up to 30 independent associated loci have been identified across the genome. Stressful and emo…","authors":"Voderholzer U, Jelinek L, Schennach R, Domschke K, Grabe HJ, Endres D.","venue":"Deutsches Arzteblatt international","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"preprint-10.64898/2026.10.14.758626","kind":"preprint","title":"SCN1A haploinsufficiency disrupts neural progenitor networks and accelerates neurogenesis in human Dravet syndrome forebrain assembloids","date":"2026-10-16","observedAt":"2026-10-19","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.10.14.758626","summary":"Dravet syndrome is a severe childhood neurological disorder caused mostly due to mutations in the sodium channel gene SCN1A. Although the disorder is widely attributed to dysfunction of inhibitory neurons, growing evidence suggests that disease mechanisms may begin much earlier during brain development. To investigate the developmental consequences of SCN1A haploinsufficiency, we generated patient-derived dorsal-ventral forebrain assembloids that model key features of human corticogenesis. We found that SCN1A was expressed in ventricular zone neural progenitors and that its reduced expression was associated with…","authors":"Dogra D, Fong H, Zhang S, Sumi T, Rosin N, Collao N, Gordon M, Korver A, Gavrilovici C, Noble D, Guzman SJ, Rohani L, Rancourt D, Biernaskie J, Jacobs-Levan J, Thompson R, Kurrasch DM.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record"]},{"id":"preprint-10.64898/2026.10.16.759637","kind":"preprint","title":"Supramodal Coding of Detection and Confidence in the Human Cortex","date":"2026-10-16","observedAt":"2026-10-19","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.10.16.759637","summary":"Perception is inherently multisensory, yet it remains unclear whether the brain detects stimuli and evaluates confidence in these detections using circuits shared across senses or circuits specific to each modality. Prior evidence is limited: scalp electrophysiology cannot localize where a shared code operates, whereas functional imaging cannot resolve its timing. We recorded intracranial activity (stereoelectroencephalography) in eight patients with epilepsy who performed a near-threshold audiovisual detection task in which they reported, on each trial, whether a visual, auditory, or audiovisual stimulus was pr…","authors":"Porte P, Robin A, Boscher F, Dezier C, Goueytes D, Mahdian S, Hoffmann D, Kahane P, Minotti L, Pereira M, Caron-Guyon J, Goupil L, Faivre N.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record"]},{"id":"preprint-10.21203/rs.3.rs-11389227/v1","kind":"preprint","title":"Emergent locomotion from anatomy alone: a whole-connectome, conductance-based neuromechanical model of Caenorhabditis elegans","date":"2026-10-16","observedAt":"2026-10-19","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.21203/rs.3.rs-11389227/v1","summary":"Abstract Ion-channel parameters in excitable cells are strongly degenerate: many distinct conductance combinations produce the same electrical behaviour. Whether this degeneracy is a nuisance or a design principle of nervous systems cannot be decided at the single-cell level. Here we test it at the whole-animal level by coupling a conductance-based model of the complete C. elegans somatic nervous system - 292 neurons, each carrying up to 17 voltage- and calcium-dependent currents whose constants are anchored to published electrophysiology - to a viscoelastic body with proprioceptive feedback. Synaptic and gap-ju…","authors":"Li H.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record"]},{"id":"paper-10.1007/s11916-026-01549-6","kind":"paper","title":"Peripheral Nerve Stimulation for Essential Tremor: a Systematic Review and Meta-Analysis of Effectiveness and Safety.","date":"2026-10-15","observedAt":"2026-10-19","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1007/s11916-026-01549-6","summary":"Background Essential tremor (ET) is the most prevalent movement disorder worldwide. There are limited current pharmacological therapies, and their side effects often preclude adequate doses. Surgical therapies, such as Deep Brain Stimulation (DBS) and Focused Ultrasound (FUS), are reserved for patients with tremor that debilitates activities of daily living (ADLs). Peripheral nerve stimulation (PNS), including transcutaneous afferent patterned stimulation (TAPS) and transcutaneous peripheral nerve stimulation (TPNS), has emerged as a promising non-invasive neuromodulatory approach for many patients with intermed…","authors":"El-Moslemani M, Abbas A, Sabet H, Almarfadi A, Mahadin M, Khanfar R, Yousef O, Hussein A, Abd-Elsayed A, Pilitsis JG.","venue":"Current pain and headache reports","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"preprint-10.64898/2026.10.13.26365259","kind":"preprint","title":"Levodopa Preferentially Reorganizes Dorsal Subthalamic Activity in Parkinsons Disease","date":"2026-10-15","observedAt":"2026-10-19","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.10.13.26365259","summary":"Background: Dopamine replacement reshapes subthalamic activity in Parkinson's disease, but whether this response reflects anatomically organized network reconfiguration remains unclear. Objectives: To determine whether levodopa preferentially reorganizes dorsal subthalamic spectral activity and cortico-subthalamic directionality. Methods: Twelve participants undergoing bilateral subthalamic deep brain stimulation contributed 30 contacts (14 dorsal, 16 ventral). Recordings obtained OFF and ON medication underwent spectral parameterization and multiband state-space analysis. Simultaneous electroencephalography in…","authors":"Nair S, Joshi P, Filyushkina V, Sayfulina K, Guha A, Sedov A, Shaikh AG.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["stimulate"]},{"id":"preprint-10.64898/2026.10.09.757963","kind":"preprint","title":"Predictive Grid Cell Coding Does Not Require Explicit Planning","date":"2026-10-15","observedAt":"2026-10-19","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.10.09.757963","summary":"Predictive grid cells, a recently discovered functional class of neurons in medial entorhinal cortex (MEC), exhibit grid-like tuning, not with respect to where an animal currently is, but where it will be. Such coding, which is disjoint from standard grid cell coding, appears consistent with the hypothesis that MEC supports predictive computations for goal-directed navigation. However, given that existing predictive coding theories have been used to understand standard grid cells, it remains unclear what the functional significance of predictive grid cells is. Furthermore, the extent to which predictive grid cel…","authors":"Sinha A, Fasehun OC, Redman WT.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record"]},{"id":"preprint-10.64898/2026.10.08.757407","kind":"preprint","title":"Movie Watching for Individual Functional Brain Network Estimation in Adolescents","date":"2026-10-15","observedAt":"2026-10-19","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.10.08.757407","summary":"Precision functional mapping (PFM) reveals stable individual differences in brain functional network organization and holds promise for advancing neuropsychiatric clinical care. PFM requires sufficient high-quality and densely-sampled functional MRI data at the individual level that is typically acquired during the so-called resting state while passively fixating on a crosshair. However, crosshair fixation acquisitions can be challenging especially for pediatric or patient populations, where alternatives like movie watching might be used to improve data quality and reduce participant burden. Here, we compare the…","authors":"Godfrey KJ, Grimsrud GJ, Ramirez JSB, Corlett A, Houlihan K, Byington N, Gell M, Kretsch S, Dosenbach NU, Barch DM, Gordon EM, Greene DJ, Mueller BA, Betzel RF, Fair DA, Conelea CA, Tervo-Clemmens B, Nelson SM.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record","stimulate"]},{"id":"preprint-10.64898/2026.10.08.757789","kind":"preprint","title":"Coupled neuro-fluid dynamics in human bioelectromagnetism","date":"2026-10-15","observedAt":"2026-10-19","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.10.08.757789","summary":"Electroencephalography (EEG) and magnetoencephalography (MEG) are widely interpreted as direct, non-invasive measures of neural population activity, assuming surrounding tissue and cerebrospinal fluid (CSF) act as passive volume conductors that distorts but do not contribute to signal generation. Using conductive-fluid phantom experiments, structural magnetic resonance imaging, and in vivo EEG and MEG recordings, the present report challenges this assumption. Mechanically driven conductive fluid generated structured, oscillatory, source-localizable electromagnetic signals resembling M/EEG in the absence of neura…","authors":"Popov T, Miller GA.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record"]},{"id":"preprint-10.31234/osf.io/582fr_v2","kind":"preprint","title":"Neuroscience-Informed Psychoeducation for Epilepsy: A Shared Language for Integrated Care","date":"2026-10-15","observedAt":"2026-10-19","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.31234/osf.io/582fr_v2","summary":"Epilepsy is among the most burdensome neurological disorders worldwide, with an impact that extends far beyond seizure frequency alone. Depression, anxiety, cognitive impairment, and internalized stigma affect a substantial proportion of individuals with epilepsy, yet these comorbidities remain systematically undertreated in routine neurological care. Conventional psychoeducation, largely centered on passive information delivery, has shown limited effectiveness in addressing the psychological and social complexities of living with epilepsy. Neuroscience-Informed Psychoeducation for Epilepsy (NIPE) offers a funda…","authors":"Elbanna I, Makke YA.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["stimulate","compute","personal"]},{"id":"paper-10.34133/bmef.0323","kind":"paper","title":"Precise Manipulation of Bubble Cavitation and Blood-Brain Barrier Modulation using Temporal Interference Ultrasound.","date":"2026-10-14","observedAt":"2026-10-19","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.34133/bmef.0323","summary":"Objective: To determine whether temporal interference (TI) ultrasound can enhance microbubble (MB) cavitation and provide transient modulation of blood-brain barrier (BBB) permeability. Impact Statement: By integrating a time-dependent multiphysics MB-vessel model with in vivo validation, this study links TI-enhanced cavitation dynamics to vessel-wall mechanical responses and a transient BBB permeability window, providing a mechanistic basis for pressure-efficient ultrasound-mediated brain delivery. Introduction: Focused ultrasound combined with MBs can transiently increase BBB permeability, but reliable control…","authors":"Jin J, Ji Z, Shangguan Z, Yan T, Qian S, Suo D.","venue":"BME frontiers","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"paper-10.1002/jum.70511","kind":"paper","title":"Microbubble Timing and Vascular Geometry Are Associated With Vessel-Level Blood-Brain Barrier Opening During Focused Ultrasound.","date":"2026-10-14","observedAt":"2026-10-19","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1002/jum.70511","summary":"Objectives To examine whether minute-scale microbubble handling and injection-to-sonication timing are associated with vessel-level focused ultrasound (FUS)-mediated blood-brain barrier opening (BBBO), and whether control normalization improves longitudinal 2-photon (2P) measurements. Methods Cranial-windowed mice received FITC-dextran (40 kDa) and SonoVue microbubbles by retro-orbital injection, followed by 1.0 MHz FUS at 0.2-0.4 MPa. Two-photon stacks were acquired over 0-15 minutes. Frangi vesselness and Otsu thresholding defined vessel masks and a perivascular ring for extravasation analysis. Three timing co…","authors":"Park S, Lee H, Choi S, Park J, Kim SK, Kim K.","venue":"Journal of ultrasound in medicine : official journal of the American Institute of Ultrasound in Medicine","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"paper-10.1523/jneurosci.0310-26.2026","kind":"paper","title":"Microglial Presenilin-1 modulates neuronal function and memory-associated behaviors.","date":"2026-10-14","observedAt":"2026-10-19","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1523/jneurosci.0310-26.2026","summary":"Microglial cells, the macrophages of the brain parenchyma, are increasingly recognized to play a key role in synaptic plasticity and function. Presenilin 1 (PS1) is an essential protein involved in learning and memory; the loss of neuronal Presenilin function causes cognitive deficits and impaired synapse plasticity in mice. Here we show memory enhancement in male mice lacking PS1 in microglia (PS1 ΔMG ). Leveraging high-throughput RNA sequencing with single-cell deconvolution-analysis, we estimate that PS1 ΔMG increases Cd52-lo microglial population, a proliferative group enriched in AP-1 responsive genes; and…","authors":"Frost PDS, Martinez CA, Millet A, McWhirt J, Cheng J, Bamkole M, Kim Y, Silva HM, Lafaille JJ, Azevedo EP, Stevens B, Ledo JH.","venue":"The Journal of neuroscience : the official journal of the Society for Neuroscience","status":"Peer-reviewed / indexed","topics":["record"]},{"id":"paper-10.1016/j.physbeh.2026.115538","kind":"paper","title":"The effect of concurrent application of the deep brain stimulation of the nucleus accumbens and cannabidiol injection during extinction period on reinstatement of METH-induced conditioned place preference in extinguished rats.","date":"2026-10-14","observedAt":"2026-10-19","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1016/j.physbeh.2026.115538","summary":"Methamphetamine (METH) is a potent stimulant drug that significantly alters the function of the central nervous system (CNS). METHS's abuse may be linked with a variety of psychiatric disorders, primarily by affecting the reward system. Cannabidiol (CBD), a primary cannabinoid component of the Cannabis plant, has been shown to affect the reward system, suggesting it for modulating addictive behaviors. On the other hand, deep brain stimulation (DBS) of the nucleus accumbens (NAc), one of the most significant brain regions implicated in mediating rewards, is effective in alleviating drug-seeking behaviors. The pre…","authors":"Mohammadi M, Zendehdel M, Haghparast A.","venue":"Physiology & behavior","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"news-nibib-0-nih-demystifies-vital-biomedical-tech-congressional-staff","kind":"news","title":"NIH Demystifies Vital Biomedical Tech for Congressional Staff","date":"2025-08-15","observedAt":"2026-10-19","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/nih-demystifies-vital-biomedical-tech-congressional-staff","summary":"Biomedical engineers and imaging researchers gave 45 congressional staff a glimpse of transformative medical technologies on the horizon, underscoring the crucial role of medical tools in human health. More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["record"]},{"id":"news-nibib-1-innovative-imaging-tool-could-improve-diagnosis-treatment-hearing-loss","kind":"news","title":"Innovative imaging tool could improve diagnosis and treatment of hearing loss","date":"2025-08-04","observedAt":"2026-10-19","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/innovative-imaging-tool-could-improve-diagnosis-treatment-hearing-loss","summary":"Researchers from the Keck School of Medicine of USC with NIH funding including NIBIB have adapted a low-cost imaging method developed for ophthalmology and used it to visualize tiny structures in the human inner ear. &nbsp; Source: USC Keck School of Medicine News. More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["record"]},{"id":"news-nibib-2-scientists-develop-high-performance-mri-scanner-effort-define-microscopic-brain-structures","kind":"news","title":"Scientists Develop High-Performance MRI Scanner in Effort to Define Microscopic Brain Structures","date":"2025-07-16","observedAt":"2026-10-19","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/scientists-develop-high-performance-mri-scanner-effort-define-microscopic-brain-structures","summary":"A scientific team supported in part by NIH has developed a new, ultra-high-resolution brain imaging system that can reconstruct microscopic brain structures that are disrupted in neurological and neuropsychiatric brain disorders. The new system is a significant advance over conventional magnetic resonance imaging (MRI) scanners that cannot visualize these tiny but clinically important structures. Source: NIH More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["record"]},{"id":"news-nibib-3-high-tech-sticker-can-identify-real-human-emotions","kind":"news","title":"High-tech sticker can identify real human emotions","date":"2025-04-22","observedAt":"2026-10-19","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/high-tech-sticker-can-identify-real-human-emotions","summary":"Saying one thing while feeling another is part of being human, but bottling up emotions can have serious psychological consequences like anxiety or panic attacks. To help health care providers tell the difference, a team led by scientists at Penn State has created a stretchable, rechargeable sticker that can detect real emotions — by measuring things like skin temperature and heart rate — even when users put on a brave face. &nbsp;The researchers recently unveiled the wearable patch that can simultaneously and accurately track multiple emotional signals in a study published in the journal Nano Letters. Read more…","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["personal"]},{"id":"news-nibib-4-your-skin-breathing-new-wearable-device-can-measure-it","kind":"news","title":"Your skin is breathing. This new wearable device can measure it.","date":"2025-04-10","observedAt":"2026-10-19","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/your-skin-breathing-new-wearable-device-can-measure-it","summary":"Northwestern University researchers have developed the first wearable device for measuring gases emitted from and absorbed by the skin. By analyzing these gases, the device offers an entirely new way to assess skin health, including monitoring wounds, detecting skin infections, tracking hydration levels, quantifying exposure to harmful environmental chemicals and more. Source: Northwestern Now More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["personal"]},{"id":"news-nibib-5-ai-tool-can-track-effectiveness-multiple-sclerosis-treatments","kind":"news","title":"AI tool can track effectiveness of multiple sclerosis treatments","date":"2025-04-08","observedAt":"2026-10-19","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/ai-tool-can-track-effectiveness-multiple-sclerosis-treatments","summary":"A new artificial intelligence (AI) tool that can help interpret and assess how well treatments are working for patients with multiple sclerosis (MS) has been developed by University College London researchers. Source: University College London News More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["compute"]},{"id":"news-nibib-6-revealing-capillaries-cells-living-organs-ultrasound","kind":"news","title":"Revealing capillaries and cells in living organs with ultrasound","date":"2025-04-04","observedAt":"2026-10-19","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/revealing-capillaries-cells-living-organs-ultrasound","summary":"While medical centers use ultrasound daily, so far this technology has not been capable of observing body tissues at the scale of cells. Physicists at several universities including CalTech have now developed a microscopy technique based on ultrasound to reveal capillaries and cells across living organs -- something that wasn't possible before. Source: Delft University of Technology More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["stimulate"]},{"id":"news-nibib-7-decreasing-invasiveness-deep-brain-stimulation","kind":"news","title":"Decreasing the invasiveness of deep brain stimulation","date":"2025-03-20","observedAt":"2026-10-19","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/decreasing-invasiveness-deep-brain-stimulation","summary":"Researchers are developing a preclinical method to stimulate the brain without drilling into the skull by guiding a catheter through the cerebrospinal fluid. More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["stimulate"]}]};
